export const updateUserRoles = <ThrowOnError extends boolean = false>(options: Options<UpdateUserRolesData, ThrowOnError>) => (options.client ?? client).put<UpdateUserRolesResponses, UpdateUserRolesErrors, ThrowOnError>({
    url: '/api/users/{realmId}/{userId}/roles',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Handle webhook events from Creem payment provider
 *
 * Processes asynchronous payment events from Creem including:
 * - `checkout.completed`: One-time payment successful
 * - `subscription.paid`: Recurring subscription payment
 * - `subscription.canceled`: Subscription canceled
 * - `subscription.expired`: Subscription period ended
 *
 * # Security
 *
 * Webhook signature is verified using HMAC-SHA256 with the webhook secret.
 *
 * # Idempotency
 *
 * Each webhook event is tracked in database to prevent duplicate processing.
 * The `creem_event_id` is used as an idempotency key.
 */
export const webhookHandler = <ThrowOnError extends boolean = false>(options: Options<WebhookHandlerData, ThrowOnError>) => (options.client ?? client).post<WebhookHandlerResponses, WebhookHandlerErrors, ThrowOnError>({
    url: '/billing/webhooks',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Health check endpoint for monitoring and orchestration
 *
 * Used by:
 * - Kubernetes liveness probes (is the service running?)
 * - Kubernetes readiness probes (can the service handle traffic?)
 * - Monitoring systems (Prometheus, Datadog, etc.)
 * - Load balancers (health checks)
 *
 * # Health Criteria
 *
 * The service is considered **healthy** when:
 * - PostgreSQL database is reachable (`SELECT 1` succeeds)
 * - Redis cache is reachable (PING succeeds)
 *
 * # Response Codes
 *
 * - **200 OK**: Service is healthy
 * - **503 Service Unavailable**: Service is unhealthy
 */
export const healthCheck = <ThrowOnError extends boolean = false>(options?: Options<HealthCheckData, ThrowOnError>) => (options?.client ?? client).get<HealthCheckResponses, HealthCheckErrors, ThrowOnError>({ url: '/health', ...options });
